/**
 * particles.min.js - 轻量粒子背景库
 * 纯本地 JS 实现，不依赖任何外部 CDN 或库
 * 用 IIFE 封装，挂载到 window.Particles
 * 初始化：Particles.init('#particles-js', {color:'#00d4ff', count:80, maxDistance:130, speed:0.5})
 */
(function (window) {
    'use strict';

    var Particles = {};

    /**
     * 在指定容器内初始化粒子背景
     * @param {string} selector 容器选择器
     * @param {Object} options 配置参数
     *   - color: 粒子颜色 (默认 '#00d4ff')
     *   - count: 粒子数量 (默认 80)
     *   - maxDistance: 连线最大距离 (默认 130)
     *   - speed: 粒子运动速度 (默认 0.5)
     *   - lineColor: 连线颜色 (默认与 color 相同)
     *   - mouseRadius: 鼠标吸附半径 (默认 180)
     *   - mouseAttraction: 鼠标吸附强度 (默认 0.02)
     */
    Particles.init = function (selector, options) {
        options = options || {};
        var config = {
            color: options.color || '#00d4ff',
            count: options.count || 80,
            maxDistance: options.maxDistance || 130,
            speed: typeof options.speed === 'number' ? options.speed : 0.5,
            lineColor: options.lineColor || options.color || '#00d4ff',
            mouseRadius: options.mouseRadius || 180,
            mouseAttraction: typeof options.mouseAttraction === 'number' ? options.mouseAttraction : 0.02,
            maxOpacity: options.maxOpacity || 0.6
        };

        var container = document.querySelector(selector);
        if (!container) {
            console.error('[Particles] 容器未找到:', selector);
            return null;
        }

        // 容器需要相对定位以便 canvas 填充
        var containerStyle = window.getComputedStyle(container);
        if (containerStyle.position === 'static') {
            container.style.position = 'relative';
        }

        var canvas = document.createElement('canvas');
        canvas.style.display = 'block';
        canvas.style.position = 'absolute';
        canvas.style.top = '0';
        canvas.style.left = '0';
        canvas.style.width = '100%';
        canvas.style.height = '100%';
        container.appendChild(canvas);

        var ctx = canvas.getContext('2d');
        var particles = [];
        var mouse = { x: null, y: null };
        var animationId = null;
        var dpr = window.devicePixelRatio || 1;

        // 将十六进制颜色转换为 RGB 数组
        function hexToRgb(hex) {
            hex = hex.replace('#', '');
            if (hex.length === 3) {
                hex = hex.split('').map(function (c) { return c + c; }).join('');
            }
            var num = parseInt(hex, 16);
            return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
        }

        var colorRgb = hexToRgb(config.color);
        var lineRgb = hexToRgb(config.lineColor);

        function resize() {
            var rect = container.getBoundingClientRect();
            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;
            canvas.style.width = rect.width + 'px';
            canvas.style.height = rect.height + 'px';
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        }

        function createParticle() {
            var rect = container.getBoundingClientRect();
            return {
                x: Math.random() * rect.width,
                y: Math.random() * rect.height,
                vx: (Math.random() - 0.5) * config.speed * 2,
                vy: (Math.random() - 0.5) * config.speed * 2,
                radius: Math.random() * 1.5 + 1
            };
        }

        function initParticles() {
            particles = [];
            for (var i = 0; i < config.count; i++) {
                particles.push(createParticle());
            }
        }

        function update() {
            var rect = container.getBoundingClientRect();
            var w = rect.width;
            var h = rect.height;

            for (var i = 0; i < particles.length; i++) {
                var p = particles[i];

                // 鼠标吸附
                if (mouse.x !== null && mouse.y !== null) {
                    var dx = mouse.x - p.x;
                    var dy = mouse.y - p.y;
                    var dist = Math.sqrt(dx * dx + dy * dy);
                    if (dist < config.mouseRadius && dist > 0) {
                        var force = (1 - dist / config.mouseRadius) * config.mouseAttraction;
                        p.vx += (dx / dist) * force;
                        p.vy += (dy / dist) * force;
                    }
                }

                // 阻尼，防止吸附后速度过大
                p.vx *= 0.99;
                p.vy *= 0.99;

                // 限制最大速度
                var maxSpeed = config.speed * 2;
                var sp = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
                if (sp > maxSpeed) {
                    p.vx = (p.vx / sp) * maxSpeed;
                    p.vy = (p.vy / sp) * maxSpeed;
                }

                p.x += p.vx;
                p.y += p.vy;

                // 边界回弹
                if (p.x < 0 || p.x > w) {
                    p.vx *= -1;
                    p.x = Math.max(0, Math.min(w, p.x));
                }
                if (p.y < 0 || p.y > h) {
                    p.vy *= -1;
                    p.y = Math.max(0, Math.min(h, p.y));
                }
            }
        }

        function draw() {
            var rect = container.getBoundingClientRect();
            ctx.clearRect(0, 0, rect.width, rect.height);

            // 画连线
            for (var i = 0; i < particles.length; i++) {
                for (var j = i + 1; j < particles.length; j++) {
                    var p1 = particles[i];
                    var p2 = particles[j];
                    var dx = p1.x - p2.x;
                    var dy = p1.y - p2.y;
                    var dist = Math.sqrt(dx * dx + dy * dy);
                    if (dist < config.maxDistance) {
                        var opacity = (1 - dist / config.maxDistance) * config.maxOpacity;
                        ctx.strokeStyle = 'rgba(' + lineRgb[0] + ',' + lineRgb[1] + ',' + lineRgb[2] + ',' + opacity + ')';
                        ctx.lineWidth = 1;
                        ctx.beginPath();
                        ctx.moveTo(p1.x, p1.y);
                        ctx.lineTo(p2.x, p2.y);
                        ctx.stroke();
                    }
                }
            }

            // 画粒子
            for (var k = 0; k < particles.length; k++) {
                var p = particles[k];
                ctx.fillStyle = 'rgba(' + colorRgb[0] + ',' + colorRgb[1] + ',' + colorRgb[2] + ',0.9)';
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
                ctx.fill();
            }
        }

        function animate() {
            update();
            draw();
            animationId = requestAnimationFrame(animate);
        }

        // 鼠标事件（相对容器）
        function onMouseMove(e) {
            var rect = container.getBoundingClientRect();
            mouse.x = e.clientX - rect.left;
            mouse.y = e.clientY - rect.top;
        }

        function onMouseLeave() {
            mouse.x = null;
            mouse.y = null;
        }

        // 触摸事件支持
        function onTouchMove(e) {
            if (e.touches && e.touches.length > 0) {
                var rect = container.getBoundingClientRect();
                mouse.x = e.touches[0].clientX - rect.left;
                mouse.y = e.touches[0].clientY - rect.top;
            }
        }

        container.addEventListener('mousemove', onMouseMove);
        container.addEventListener('mouseleave', onMouseLeave);
        container.addEventListener('touchmove', onTouchMove);
        container.addEventListener('touchend', onMouseLeave);
        window.addEventListener('resize', function () {
            resize();
            initParticles();
        });

        // 启动
        resize();
        initParticles();
        animate();

        // 返回控制器，便于销毁
        return {
            destroy: function () {
                if (animationId) {
                    cancelAnimationFrame(animationId);
                }
                container.removeEventListener('mousemove', onMouseMove);
                container.removeEventListener('mouseleave', onMouseLeave);
                container.removeEventListener('touchmove', onTouchMove);
                container.removeEventListener('touchend', onMouseLeave);
                if (canvas.parentNode) {
                    canvas.parentNode.removeChild(canvas);
                }
                particles = [];
            },
            resize: function () {
                resize();
                initParticles();
            }
        };
    };

    window.Particles = Particles;
})(window);
